) values (
  'bb3b6e54-9b58-565a-80b1-9824dd793faa'::uuid, null, 'Mind Flayarrrs', 'commander', 'Mind Flayarrrs is an official Commander precon from CLB, released 2022-06-10.', 'public', true, true,
