  commander_image_uri, commander_art_uri, commander_color_identity, colors
) values (
  '82855868-7624-5dd3-b06e-4c0a34b85943'::uuid, null, 'Forces of the Imperium Collector''s Edition', 'commander', 'Forces of the Imperium Collector''s Edition is an official Commander precon from 40K, released 2022-10-07.', 'public', true, true,
