  'https://cards.scryfall.io/normal/front/8/6/86a4afac-69fd-46e9-8009-58de59bf3f5c.jpg', 'https://cards.scryfall.io/art_crop/front/8/6/86a4afac-69fd-46e9-8009-58de59bf3f5c.jpg', ARRAY['W', 'U', 'B']::text[], ARRAY['W', 'U', 'B']::text[]
) on conflict (id) do update set
  owner_id = excluded.owner_id,
  name = excluded.name,
  format = excluded.format,
  notes = excluded.notes,
  visibility = excluded.visibility,
