  'd3bdb0d8-b839-5337-9570-baf9f19aad08'::uuid, null, 'Chaos Incarnate', 'commander', 'Chaos Incarnate is an official Commander precon from SCD, released 2022-12-02.', 'public', true, true,
  '19e4d494-e8b3-4ae2-93e3-70c65ab90f15', 'Kardur, Doomscourge', 'Legendary Creature — Demon Berserker', '{2}{B}{R}',
  'https://cards.scryfall.io/normal/front/1/9/19e4d494-e8b3-4ae2-93e3-70c65ab90f15.jpg', 'https://cards.scryfall.io/art_crop/front/1/9/19e4d494-e8b3-4ae2-93e3-70c65ab90f15.jpg', ARRAY['B', 'R']::text[], ARRAY['B', 'R']::text[]
) on conflict (id) do update set
  owner_id = excluded.owner_id,
  name = excluded.name,
  format = excluded.format,
  notes = excluded.notes,
  visibility = excluded.visibility,
  allow_forks = excluded.allow_forks,
  is_precon = excluded.is_precon,
  commander_scryfall_id = excluded.commander_scryfall_id,
  commander_name = excluded.commander_name,
  commander_type_line = excluded.commander_type_line,
  commander_mana_cost = excluded.commander_mana_cost,
  commander_image_uri = excluded.commander_image_uri,
  commander_art_uri = excluded.commander_art_uri,
  commander_color_identity = excluded.commander_color_identity,
  colors = excluded.colors,
  updated_at = now()
where decks.is_precon or decks.owner_id is null;

