Flashback {8}{G}{G} (You may cast this card from your graveyard for its flashback cost. Then exile it.)', 1, 'main')
) as v(deck_id, scryfall_id, card_name, image_uri, mana_cost, type_line, colors, color_identity, oracle_text, quantity, board)
where exists (
  select 1 from public.decks d
  where d.id = v.deck_id and (d.is_precon or d.owner_id is null)
)
on conflict (deck_id, scryfall_id, board) do update set
  card_name = excluded.card_name,
  image_uri = excluded.image_uri,
  mana_cost = excluded.mana_cost,
  type_line = excluded.type_line,
  colors = excluded.colors,
  color_identity = excluded.color_identity,
  oracle_text = excluded.oracle_text,
  quantity = excluded.quantity
where exists (
  select 1 from public.decks d
  where d.id = public.deck_cards.deck_id and (d.is_precon or d.owner_id is null)
);

